// Actual C3 read-only status aggregation. No provider is probed and no memory store is opened.
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {readFileSync,writeFileSync,readdirSync} from 'node:fs';
import path from 'node:path';import {pathToFileURL} from 'node:url';
const root=process.env.PLUR1BUS_ENGINE_SRC;assert.ok(root);assert.equal(process.version,'v24.21.0');
const source=JSON.parse(readFileSync(new URL('./status-sources.json',import.meta.url),'utf8'));
const files=[];function walk(dir){for(const e of readdirSync(dir,{withFileTypes:true})){const f=path.join(dir,e.name);if(e.isDirectory())walk(f);else if(e.name.endsWith('.js'))files.push(f);}}
walk(path.join(root,'engine'));walk(path.join(root,'lib'));const hash=createHash('sha256');for(const f of files.sort()){hash.update(`${path.relative(root,f)}\0`);hash.update(readFileSync(f));hash.update('\0');}assert.equal(hash.digest('hex'),source.treeSha256);
const {createStatusReporter,normalizeJournalBacklog}=await import(pathToFileURL(path.join(root,'engine/status/status-reporter.js')));
const identity={fingerprintId:'fixture-identity',provider:'local-transformers',model:'synthetic-model',dimensions:4};
const model=(embedder='ready',reranker='disabled')=>({embedder:{state:embedder,warming:embedder==='loading',checkedAt:embedder==='loading'?null:1000,identity,...(embedder==='failed'?{error:'provider-failed'}:{})},reranker:{state:reranker,warming:reranker==='loading',checkedAt:reranker==='loading'||reranker==='disabled'?null:1000,provider:reranker==='disabled'?null:'local-transformers',...(reranker==='failed'?{error:'provider-failed'}:{})}});
const defs=[];for(const e of ['ready','loading','failed'])for(const r of ['disabled','ready','loading','failed'])defs.push({name:`models-${e}-${r}`,models:model(e,r)});
defs.push({name:'jobs-failure',jobsFailure:true},{name:'models-failure',modelsFailure:true},{name:'identity-failure',modelsFailure:true,identityFailure:true},{name:'identity-missing',modelsFailure:true,noIdentity:true},{name:'shared-failure',sharedFailure:true},{name:'unknown-schema',current:'7'},{name:'legacy-schema',current:'0'},{name:'unreadable-schema',current:null},{name:'opened-agents',agents:7},{name:'shared-fd-capability',shared:{supported:true,mode:'fd-capability'}},{name:'shared-verified-path',shared:{supported:true,mode:'verified-path'}},{name:'shared-unsafe-root',shared:{supported:false,mode:'unavailable',reason:'unsafe-root'}},{name:'journal-absent',noJournal:true},{name:'journal-null',journal:null},{name:'journal-empty',journal:{entries:0,oldestAt:null}},{name:'journal-pending',journalNever:true},{name:'journal-throws',journalFailure:true},{name:'journal-invalid-count',journal:{entries:-1,oldestAt:null}},{name:'journal-extra',journal:{entries:3,oldestAt:1,extra:'discarded'}},{name:'journal-invalid-time',journal:{entries:1,oldestAt:'1'}});
const defaults={models:model(),jobs:{ledger:'ok',agents:[]},shared:{supported:false,mode:'unavailable',reason:'platform'},current:'1',agents:0,journal:{entries:2,oldestAt:1000}};
async function record(){const out=[];for(const def of defs){const c={...defaults,...def};const calls={jobs:0,models:0,identity:0,shared:0,current:0,journal:0};const reporter=createStatusReporter({contract:'1.17.0',expectedSchema:'1',openedAgents:{size:c.agents},jobs:{health(){calls.jobs++;if(c.jobsFailure)throw new Error('synthetic');return c.jobs;}},models:{status(){calls.models++;if(c.modelsFailure)throw new Error('synthetic');return c.models;}},getIdentity:()=>{calls.identity++;if(c.identityFailure)throw new Error('synthetic');return c.noIdentity?null:identity;},sharedMemoryPool:{support(){calls.shared++;if(c.sharedFailure)throw new Error('synthetic');return c.shared;}},storeMigrator:{current(){calls.current++;return c.current;}},host:{logger:{debug(){}},capabilities:c.noJournal?{}:{journalBacklog(){calls.journal++;if(c.journalFailure)throw new Error('synthetic');if(c.journalNever)return new Promise(()=>{});return c.journal;}}}});out.push({...c,result:await reporter.status(),calls});}return out;}
const normalizers=[null,false,0,'x',[],{}, {entries:0,oldestAt:null},{entries:1,oldestAt:0},{entries:1.5,oldestAt:null},{entries:-1,oldestAt:0},{entries:9007199254740991,oldestAt:-1},{entries:9007199254740992,oldestAt:null},{entries:'1',oldestAt:null},{entries:1},{entries:1,oldestAt:'1'},{entries:1,oldestAt:false},{entries:1,oldestAt:1.5,extra:2}].map(input=>({input,result:normalizeJournalBacklog(input)}));
async function overlap(){let calls=0;const reporter=createStatusReporter({contract:'1.17.0',expectedSchema:'1',openedAgents:{size:0},jobs:{health:()=>defaults.jobs},models:{status:()=>defaults.models},getIdentity:()=>identity,sharedMemoryPool:{support:()=>defaults.shared},storeMigrator:{current:()=> '1'},host:{logger:{debug(){}},capabilities:{journalBacklog(){calls++;return new Promise(()=>{});}}}});const results=await Promise.all(Array.from({length:4},()=>reporter.status()));return {journalCalls:calls,journals:results.map(r=>r.journal)};}
const cases=await record();assert.deepEqual(await record(),cases);const concurrent=await overlap();assert.deepEqual(await overlap(),concurrent);writeFileSync(new URL('./golden/status.json',import.meta.url),JSON.stringify({recordedFrom:{source,node:process.version},identity,cases,normalizers,concurrent},null,2)+'\n');console.log(`Recorded ${cases.length} actual Node status cases twice and ${normalizers.length} normalizer cases`);
